const results = [];

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  if (!item.binary) continue;

  for (const key of Object.keys(item.binary)) {
    const bin = item.binary[key];

    const isPdf =
      (bin.mimeType && bin.mimeType.toLowerCase().includes('pdf')) ||
      (bin.fileName && bin.fileName.toLowerCase().endsWith('.pdf'));

    if (!isPdf) continue;

    const binaryData = await this.helpers.getBinaryDataBuffer(i, key);
    const base64 = binaryData.toString('base64');

    results.push({
      json: {
        success: true,
        pdfDetected: true,
        fileName: bin.fileName || 'attachment.pdf',
        mimeType: bin.mimeType || 'application/pdf',
        pdfUrl: `data:${bin.mimeType || 'application/pdf'};base64,${base64}`,
        subject: item.json.subject || item.json.Subject || null,
        from: item.json.from || item.json.From || null,
        receivedAt: item.json.date || item.json.Date || null
      },
      binary: {
        data: bin
      }
    });
  }
}

if (results.length === 0) {
  const first = items[0]?.json || {};

  return [{
    json: {
      success: false,
      pdfDetected: false,
      fileName: null,
      mimeType: null,
      pdfUrl: null,
      subject: first.subject || first.Subject || null,
      from: first.from || first.From || null,
      receivedAt: first.date || first.Date || null
    }
  }];
}

return results;

const input = $json;

// Get the AI Agent output.
// Change this if your AI Agent stores the response under a different field.
let raw = input.output || input.text || input.response || input;

let data;

// Parse JSON if it is a string
if (typeof raw === 'string') {
  try {
    // Remove markdown code fences if the AI added them
    raw = raw
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    data = JSON.parse(raw);
  } catch (error) {
    // Don't crash the execution on a malformed AI response — flag it for review instead
    return [{
      json: {
        parseError: true,
        parseErrorMessage: error.message,
        rawOutput: raw,
        status: 'missing_information'
      }
    }];
  }
} else {
  data = raw;
}

// Create simple string values for n8n
return [
  {
    json: {
      invoice_number: String(data.invoice?.invoice_number ?? ''),
      vendor_name: String(data.invoice?.vendor_name ?? ''),
      vendor_id: String(
        data.vendor_validation?.vendor_id ??
        data.invoice?.vendor_id ??
        ''
      ),

      invoice_date: String(data.invoice?.invoice_date ?? ''),
      due_date: String(data.invoice?.due_date ?? ''),
      po_number: String(data.invoice?.po_number ?? ''),
      currency: String(data.invoice?.currency ?? ''),

      subtotal: String(data.invoice?.subtotal ?? ''),
      tax: String(data.invoice?.tax ?? ''),
      total: String(
        data.amount_validation?.invoice_total ??
        data.invoice?.total ??
        ''
      ),

      payment_terms: String(data.invoice?.payment_terms ?? ''),

      vendor_status: String(
        data.vendor_validation?.status ?? ''
      ),

      vendor_found: String(
        data.vendor_validation?.vendor_found ?? false
      ),

      is_duplicate: String(
        data.duplicate_check?.is_duplicate ?? false
      ),

      matching_invoice_id: String(
        data.duplicate_check?.matching_invoice?.invoice_id ?? ''
      ),

      po_status: String(
        data.po_validation?.status ?? ''
      ),

      po_found: String(
        data.po_validation?.po_found ?? false
      ),

      vendor_match: String(
        data.po_validation?.vendor_match ?? false
      ),

      items_match: String(
        data.po_validation?.items_match ?? false
      ),

      quantities_match: String(
        data.po_validation?.quantities_match ?? false
      ),

      prices_match: String(
        data.po_validation?.prices_match ?? false
      ),

      amount_match: String(
        data.po_validation?.amount_match ?? false
      ),

      amount_status: String(
        data.amount_validation?.amount_status ?? ''
      ),

      threshold: String(
        data.amount_validation?.threshold ?? 10000
      ),

      status: String(data.status ?? ''),

      next_action: String(data.next_action ?? ''),

      issues: Array.isArray(data.issues)
        ? data.issues.join(', ')
        : String(data.issues ?? ''),

      discrepancies: Array.isArray(
        data.po_validation?.discrepancies
      )
        ? data.po_validation.discrepancies.join(', ')
        : String(data.po_validation?.discrepancies ?? ''),

      // Keep the complete line items as a string
      line_items: JSON.stringify(
        data.invoice?.line_items ?? []
      )
    }
  }
];

const reject = $json.data?.Reject;
const approve = $json.data?.Approve;

let status;

if (reject === 'Rejected') {
  status = 'Rejected';
} else if (approve === 'Approved') {
  status = 'Approved';
}

return [
  {
    json: {
      status: status
    }
  }
];

const randomNumber = Math.floor(100 + Math.random() * 900);

const status = $json.status;
const source = $json.source;

let reason;

if (source === 'FINANCIAL_MANAGER') {
  reason = 'FINANCIAL MANAGER';
} else {
  reason = 'AI AGENT';
}

return [
  {
    json: {
      ...$json,
      approver_id: `APR${randomNumber}`,
      status: status,
      reason: reason
    }
  }
];

// Re-attach the original PDF binary (lost earlier through the AI Agent / Code nodes)
